      527→  async preflightWorkspace(
      528→    cwd: string,
      529→    workspaceEffects = true,
      530→    signal?: AbortSignal,
      531→    plannedSandboxNames: readonly string[] = [],
      532→  ): Promise<void> {
      533→    this.activePreflights += 1;
