      538→        // workspace sale ferait donc calculer le Pipeline Change Set depuis une
      539→        // base différente de celle que la Promotion doit avancer atomiquement.
      540→        const status = await this.requireSuccess({
      541→          command: 'git',
      542→          args: [
      543→            'status',
      544→            '--porcelain=v1',
      545→            '--',
      546→            '.',
      547→            ':(exclude).acp/logs',
      548→            ':(exclude).acp/runs-v3',
      549→          ],
      550→          cwd,
      551→          stdin: 'ignore',
      552→          signal,
      553→        }, 'inspect the Git workspace');
      554→        if (status.stdout.trim()) {
      555→          throw new Error('Docker Sandbox requires a clean Git workspace for workspace-writing pipelines: sbx --clone cannot see uncommitted changes, so safe Promotion is impossible. Commit or remove the local changes and retry.');
      556→        }
