      558→      const version = await this.requireSuccess({ command: 'sbx', args: ['version'], cwd, stdin: 'ignore', signal }, 'read the Docker Sandbox version');
      559→      const actual = extractVersion(`${version.stdout}\n${version.stderr}`);
      560→      if (!actual || compareVersions(actual, MINIMUM_SBX_VERSION) < 0) {
      561→        throw new Error(`Docker Sandbox sbx ${MINIMUM_SBX_VERSION} or newer is required (found ${actual ?? 'an unknown version'}). Upgrade Docker Sandboxes (sbx) and retry.`);
      562→      }
      563→      await this.requireCapability(cwd, ['create', '--help'], '--clone', signal);
      564→      await this.requireCapability(cwd, ['ls', '--help'], '--json', signal);
      565→      if (plannedSandboxNames.length > 0) {
      566→        const listed = await this.requireSuccess({
      567→          command: 'sbx', args: ['ls', '--json'], cwd, stdin: 'ignore', signal,
      568→        }, 'check planned Docker Sandbox names');
