      754→export function createNodeSubprocessExecutor(): SubprocessExecutor {
      755→  return request => new Promise((resolve, reject) => {
      756→    const child = spawn(request.command, request.args, {
      757→      cwd: request.cwd,
      758→      stdio: ['ignore', 'pipe', 'pipe'],
      759→      signal: request.signal,
      760→      env: request.env ? { ...process.env, ...request.env } : process.env,
      761→    });
      762→    let stdout = '';
      763→    let stderr = '';
      764→    let settled = false;
      765→    const resolveOnce = (result: SubprocessResult): void => {
      766→      if (settled) return;
      767→      settled = true;
      768→      resolve(result);
      769→    };
      770→    child.stdout.setEncoding('utf8');
      771→    child.stderr.setEncoding('utf8');
      772→    child.stdout.on('data', chunk => { stdout += chunk; if (request.observeOutput) process.stdout.write(chunk); });
      773→    child.stderr.on('data', chunk => { stderr += chunk; if (request.observeOutput) process.stderr.write(chunk); });
      774→    child.once('error', error => {
      775→      if (request.signal?.aborted) {
      776→        resolveOnce({
      777→          exitCode: 1,
      778→          stdout,
      779→          stderr: stderr || (error instanceof Error ? error.message : String(error)),
      780→        });
      781→        return;
      782→      }
      783→      if (settled) return;
      784→      settled = true;
      785→      reject(error);
      786→    });
      787→    child.once('close', code => resolveOnce({ exitCode: code ?? 1, stdout, stderr }));
      788→  });
      789→}
