      791→function createExecutionSignal(parent: AbortSignal | undefined, timeoutMs: number | undefined): {
      792→  signal: AbortSignal;
      793→  timedOut(): boolean;
      794→  dispose(): void;
      795→} {
      796→  const controller = new AbortController();
      797→  let timeoutTriggered = false;
      798→  const abortFromParent = (): void => controller.abort(parent?.reason);
      799→  if (parent?.aborted) {
      800→    abortFromParent();
      801→  } else {
      802→    parent?.addEventListener('abort', abortFromParent, { once: true });
      803→  }
      804→
      805→  let timer: NodeJS.Timeout | undefined;
      806→  if (timeoutMs !== undefined && Number.isFinite(timeoutMs) && timeoutMs > 0) {
      807→    timer = setTimeout(() => {
      808→      timeoutTriggered = true;
      809→      controller.abort();
      810→    }, timeoutMs);
      811→  }
      812→
      813→  return {
      814→    signal: controller.signal,
      815→    timedOut: () => timeoutTriggered,
      816→    dispose: () => {
      817→      if (timer) clearTimeout(timer);
      818→      parent?.removeEventListener('abort', abortFromParent);
      819→    },
      820→  };
      821→}
